// ---- WMO weather code (Open-Meteo "weather_code") -> glyph ----
//   0 clear | 1 mainly clear | 2 partly cloudy | 3 overcast | 45,48 fog | 51-57 drizzle | 61,63,66,80,81 rain
//   65,67,82 heavy rain | 71-77,85,86 snow | 95,96,99 thunder. WIND has no WMO code: use it when the code is 0..3 and
//   wind >= WX_WIND_KMH (caller decides). is_day: Open-Meteo "is_day" (1/0).
#define WX_WIND_KMH 40
static inline wx_glyph_t wx_from_wmo(uint8_t code, uint8_t is_day) {
  switch (code) {
    case 0:  return is_day ? WX_CLEAR_DAY : WX_CLEAR_NIGHT;
    case 1: case 2: return is_day ? WX_PARTLY_DAY : WX_PARTLY_NIGHT;
    case 3:  return WX_CLOUDY;
    case 45: case 48: return WX_FOG;
    case 51: case 53: case 55: case 56: case 57: return WX_DRIZZLE;
    case 61: case 63: case 66: case 80: case 81: return WX_RAIN;
    case 65: case 67: case 82: return WX_HEAVY_RAIN;
    case 71: case 73: case 75: case 77: case 85: case 86: return WX_SNOW;
    case 95: case 96: case 99: return WX_THUNDER;
    default: return WX_CLOUDY;
  }
}
static inline const WxGlyph *wx_glyph(wx_glyph_t id, uint8_t size) {   // size 24 / 32 / 48 (48 falls back to 32)
  if (size >= 48 && WX_GLYPHS_48[id].n_layers) return &WX_GLYPHS_48[id];
  return size >= 32 ? &WX_GLYPHS_32[id] : &WX_GLYPHS_24[id];
}
// layers per glyph: CLEAR_DAY=SUN; CLEAR_NIGHT=MOON; PARTLY_DAY=SUN+CLOUD; PARTLY_NIGHT=MOON+CLOUD; CLOUDY=CLOUD_DARK+CLOUD; FOG=CLOUD+FOG; DRIZZLE=CLOUD+RAIN; RAIN=CLOUD+RAIN; HEAVY_RAIN=CLOUD_DARK+RAIN; THUNDER=CLOUD_DARK+BOLT; SNOW=CLOUD+SNOW; WIND=FOG
// Flash: 24 px 6048 B, 32 px 10752 B, 48 px 3456 B (+ 3 x 12 glyph tables)
